#!/usr/bin/env python3
from pathlib import Path
import json, statistics, csv
import pandas as pd
import matplotlib.pyplot as plt

ROOT=Path(__file__).resolve().parents[2];RES=ROOT/'experiments/results';ASSETS=RES/'assets';ASSETS.mkdir(parents=True,exist_ok=True)
raw=json.loads((RES/'performance-raw.json').read_text());assert raw['complete'] and len(raw['runs'])==9 and all(x['passed'] for x in raw['runs'])
runs=pd.DataFrame(raw['runs']).sort_values(['size','repeat']);cols=['code','size','repeat','batchId','requestSeconds','approvalToIssuedSeconds','endToEndSeconds','secondsPerCertificate','throughputCertificatesPerSecond','successRatePercent','issued','failed','transactionCount','uniqueCertificateIds','blockDelta','confirmations','cpuAveragePercent','cpuMaxPercent','memoryUsedAverageMb','memoryUsedMaxMb','backendRssAverageMb','backendRssMaxMb','passed'];runs[cols].to_csv(RES/'performance-runs.csv',index=False)
summary=[]
for size,g in runs.groupby('size'):
 row={'size':int(size),'repetitions':len(g),'totalIssued':int(g.issued.sum()),'totalFailed':int(g.failed.sum()),'successRatePercent':float(100*g.issued.sum()/(g.issued.sum()+g.failed.sum())),'transactionTotal':int(g.transactionCount.sum()),'transactionPerBatch':float(g.transactionCount.mean()),'verificationSamplesValid':int(sum(len(x) for x in g.verificationSamples))}
 for col in ['requestSeconds','approvalToIssuedSeconds','endToEndSeconds','secondsPerCertificate','throughputCertificatesPerSecond','cpuAveragePercent','cpuMaxPercent','memoryUsedAverageMb','memoryUsedMaxMb','backendRssAverageMb','backendRssMaxMb']:
  vals=[float(x) for x in g[col]];row[col+'Mean']=statistics.mean(vals);row[col+'Std']=statistics.stdev(vals);row[col+'Min']=min(vals);row[col+'Max']=max(vals)
 summary.append(row)
sdf=pd.DataFrame(summary);sdf.to_csv(RES/'performance-summary.csv',index=False);(RES/'performance-summary.json').write_text(json.dumps({'kind':'OFFICIAL_BATCH_PERFORMANCE_SUMMARY','sourceTag':raw['sourceTag'],'runs':9,'totalCertificates':int(runs.issued.sum()),'totalTransactions':int(runs.transactionCount.sum()),'allPassed':True,'bySize':summary},ensure_ascii=False,indent=2)+'\n')
sc=json.loads((RES/'official-scenarios-1-and-3-raw.json').read_text())
scenario1=[('Chứng thư gốc','VALID',sc['verification']['original'],sc['verification']['original']=='VALID'),('Sửa tên người nhận','Không VALID',sc['verification']['tampered']['recipientName'],sc['verification']['tampered']['recipientName']!='VALID'),('Sửa tên văn bằng','Không VALID',sc['verification']['tampered']['credentialName'],sc['verification']['tampered']['credentialName']!='VALID'),('Sửa proofValue','Không VALID',sc['verification']['tampered']['proofValue'],sc['verification']['tampered']['proofValue']!='VALID'),('Sửa txid trong proof','Không VALID',sc['verification']['tampered']['txid'],sc['verification']['tampered']['txid']!='VALID'),('Maker tự duyệt','HTTP 403',str(sc['rbac']['makerSelfApprove']),sc['rbac']['makerSelfApprove']==403)]
scenario3=[('Trước thu hồi','VALID',sc['verification']['original'],sc['verification']['original']=='VALID'),('Student thu hồi','HTTP 403',str(sc['rbac']['studentRevoke']),sc['rbac']['studentRevoke']==403),('Maker thu hồi','HTTP 403',str(sc['rbac']['makerRevoke']),sc['rbac']['makerRevoke']==403),('Checker thu hồi','HTTP 201',str(sc['rbac']['checkerRevoke']),sc['rbac']['checkerRevoke']==201),('Sau thu hồi','REVOKED',sc['verification']['afterRevoke'],sc['verification']['afterRevoke']=='REVOKED'),('Tx thu hồi xác nhận','>=1',str(sc['revocation']['confirmations']),sc['revocation']['confirmations']>=1),('Có trong Revocation List','true',str(sc['revocation']['listed']).lower(),sc['revocation']['listed']),('Audit đủ role/action','4 action','/'.join(x['action'] for x in sc['audit']),len(sc['audit'])==4 and all(x['actorRole'] in ['maker','checker'] for x in sc['audit']))]
for num,rows in [(1,scenario1),(3,scenario3)]:
 with (RES/f'scenario-{num}-summary.csv').open('w',newline='',encoding='utf-8') as f:
  w=csv.writer(f);w.writerow(['case','expected','observed','passed']);w.writerows(rows)
 (RES/f'scenario-{num}-summary.json').write_text(json.dumps({'scenario':num,'passed':all(x[3] for x in rows),'passedCases':sum(x[3] for x in rows),'totalCases':len(rows),'cases':[{'case':a,'expected':b,'observed':c,'passed':d} for a,b,c,d in rows]},ensure_ascii=False,indent=2)+'\n')
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.titlesize':12,'axes.labelsize':10})
# Chart 1: total processing time.
fig,ax=plt.subplots(figsize=(8,4.8));x=sdf['size'];y=sdf['approvalToIssuedSecondsMean'];e=sdf['approvalToIssuedSecondsStd'];bars=ax.bar(x.astype(str),y,yerr=e,capsize=5,color='#356aa0');ax.set(title='Thời gian phát hành batch chính thức (3 lần lặp)',xlabel='Số chứng thư trong batch',ylabel='Thời gian từ duyệt đến issued (giây)');ax.grid(axis='y',alpha=.25);[ax.text(b.get_x()+b.get_width()/2,b.get_height()+max(e)*.25,f'{v:.2f}s',ha='center') for b,v in zip(bars,y)];fig.tight_layout();fig.savefig(ASSETS/'01-thoi-gian-batch.png',dpi=220);plt.close(fig)
# Chart 2: throughput and seconds/cert.
fig,ax=plt.subplots(figsize=(8,4.8));ax.plot(x,sdf['throughputCertificatesPerSecondMean'],marker='o',linewidth=2,color='#1b7f5a',label='Thông lượng (chứng thư/giây)');ax.set(xlabel='Số chứng thư trong batch',ylabel='Chứng thư/giây');ax.grid(alpha=.25);ax2=ax.twinx();ax2.plot(x,sdf['secondsPerCertificateMean'],marker='s',linewidth=2,color='#b4512c',label='Giây/chứng thư');ax2.set_ylabel('Giây/chứng thư');ax.set_title('Hiệu quả Merkle batching');lines=ax.lines+ax2.lines;ax.legend(lines,[l.get_label() for l in lines],loc='center right');fig.tight_layout();fig.savefig(ASSETS/'02-thong-luong-hieu-qua.png',dpi=220);plt.close(fig)
# Chart 3: resources.
fig,ax=plt.subplots(figsize=(8,4.8));width=.35;idx=range(len(x));ax.bar([i-width/2 for i in idx],sdf['cpuAveragePercentMean'],width,label='CPU trung bình (%)',color='#6c5b9c');ax.set_xticks(list(idx),[str(v) for v in x]);ax.set(xlabel='Số chứng thư trong batch',ylabel='CPU trung bình (%)',title='Tài nguyên khi phát hành batch');ax2=ax.twinx();ax2.bar([i+width/2 for i in idx],sdf['memoryUsedMaxMbMean'],width,label='RAM dùng tối đa (MB)',color='#d69c2f');ax2.set_ylabel('RAM dùng tối đa (MB)');lines=[ax.patches[0],ax2.patches[0]];ax.legend(lines,['CPU trung bình (%)','RAM dùng tối đa (MB)'],loc='upper left');ax.grid(axis='y',alpha=.2);fig.tight_layout();fig.savefig(ASSETS/'03-tai-nguyen.png',dpi=220);plt.close(fig)
# Chart 4: scenario pass counts.
fig,ax=plt.subplots(figsize=(8,4.5));labels=['Kịch bản 1\nTính đúng/toàn vẹn','Kịch bản 2\nHiệu năng batch','Kịch bản 3\nThu hồi/RBAC/audit'];passed=[sum(x[3] for x in scenario1),9,sum(x[3] for x in scenario3)];total=[len(scenario1),9,len(scenario3)];bars=ax.bar(labels,[100*p/t for p,t in zip(passed,total)],color=['#356aa0','#1b7f5a','#6c5b9c']);ax.set_ylim(0,110);ax.set_ylabel('Tỷ lệ ca/lần chạy đạt (%)');ax.set_title('Kết quả ba kịch bản thực nghiệm chính thức');ax.grid(axis='y',alpha=.25);[ax.text(b.get_x()+b.get_width()/2,101,f'{p}/{t}',ha='center',fontweight='bold') for b,p,t in zip(bars,passed,total)];fig.tight_layout();fig.savefig(ASSETS/'04-tong-hop-kich-ban.png',dpi=220);plt.close(fig)
print(json.dumps({'runs':len(runs),'totalCertificates':int(runs.issued.sum()),'summary':[{k:(round(v,4) if isinstance(v,float) else v) for k,v in row.items() if k in ['size','approvalToIssuedSecondsMean','approvalToIssuedSecondsStd','throughputCertificatesPerSecondMean','secondsPerCertificateMean','cpuAveragePercentMean','memoryUsedMaxMbMean']} for row in summary],'scenario1':f'{sum(x[3] for x in scenario1)}/{len(scenario1)}','scenario3':f'{sum(x[3] for x in scenario3)}/{len(scenario3)}','assets':len(list(ASSETS.glob('*.png')))},ensure_ascii=False))
